int init_pdl_alignment_proto_struct(void)
{
    protocol_t *protocol_struct;
    size_t i;

    /* mmt-dpi ignores a protocol name that is already registered (names
     * compare case-insensitively): refuse to load instead. */
    if (get_protocol_id_by_name(PROTO_PDL_ALIGNMENT_ALIAS) != 0) {
        mmt_log_error("init_pdl_alignment_proto_struct: protocol name %s is already registered", PROTO_PDL_ALIGNMENT_ALIAS);
        return 0;
    }
    protocol_struct = init_protocol_struct_for_registration(PROTO_PDL_ALIGNMENT, PROTO_PDL_ALIGNMENT_ALIAS);
    if (protocol_struct == NULL) {
        mmt_log_error("init_pdl_alignment_proto_struct: protocol id %d is out of range or already registered", PROTO_PDL_ALIGNMENT);
        return 0;
    }
    for (i = 0; i < sizeof(pdl_alignment_attributes_metadata) / sizeof(pdl_alignment_attributes_metadata[0]); i++) {
        if (!register_attribute_with_protocol(protocol_struct, &pdl_alignment_attributes_metadata[i])) {
            mmt_log_error("init_pdl_alignment_proto_struct: cannot register attribute %s", pdl_alignment_attributes_metadata[i].alias);
            return 0;
        }
    }
    if (!register_protocol(protocol_struct, PROTO_PDL_ALIGNMENT)) {
        mmt_log_error("init_pdl_alignment_proto_struct: cannot register protocol %d", PROTO_PDL_ALIGNMENT);
        return 0;
    }
    /* User code (src/pdl_alignment_impl.c) attaches the protocol to its parents. */
    if (!pdl_alignment_hook_register_parents(protocol_struct)) {
        mmt_log_error("init_pdl_alignment_proto_struct: pdl_alignment_hook_register_parents() failed");
        return 0;
    }
    return 1;
}

#ifndef CORE
int init_proto(void)
{
    return init_pdl_alignment_proto_struct();
}
#endif
